class RemoteNode:
    def __init__(self, ip, username, password):
        self.ip = ip
        self.username = username
        self.password = password
        self.client = None

    def connect(self, use_key=False, key_path=None):
        """Establish SSH connection to target host."""
        self.client = paramiko.SSHClient()
        self.client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        try:
            if use_key and key_path:
                print(f"[{self.ip}] Connecting using SSH key: {key_path}...")
                self.client.connect(self.ip, username=self.username, key_filename=key_path, timeout=15)
            else:
                print(f"[{self.ip}] Connecting using password credentials...")
                self.client.connect(self.ip, username=self.username, password=self.password, timeout=15)
            return True
        except Exception as e:
            return False

    def execute(self, command, check_exit=True):
        """Execute command on remote node."""
        if not self.client:
            raise Exception("SSH Client is not connected.")
        
        stdin, stdout, stderr = self.client.exec_command(command)
        exit_status = stdout.channel.recv_exit_status()
        
        out_str = stdout.read().decode('utf-8').strip()
        err_str = stderr.read().decode('utf-8').strip()
        
        if check_exit and exit_status != 0:
            raise Exception(f"Command '{command}' failed with exit code {exit_status}.\nSTDOUT: {out_str}\nSTDERR: {err_str}")
        
        return exit_status, out_str, err_str


    def write_file(self, path, content):
        """Write content to a file on the remote host using SFTP.

        Text is normalized to LF. Everything written here lands on a Linux host, and a
        CRLF working tree on the provisioning workstation (git core.autocrlf=true, the
        Windows default) otherwise ships CRLF into /usr/local/bin, where a shebang of
        `#!/usr/bin/env python3\r` fails with "'python3\r': No such file or directory".
        """
        if not self.client:
            raise Exception("SSH Client is not connected.")
        if isinstance(content, str):
            content = content.replace("\r\n", "\n")
        elif isinstance(content, (bytes, bytearray)):
            content = bytes(content).replace(b"\r\n", b"\n")
        sftp = self.client.open_sftp()
        try:
            dir_name = os.path.dirname(path)
            self.execute(f"mkdir -p {dir_name}")
            f = sftp.open(path, "w")
            f.write(content)
            f.close()
        finally:
            sftp.close()

    def upload_directory(self, local_path, remote_path):
        """Upload a local directory structure to a remote path using SFTP."""
        if not self.client:
            raise Exception("SSH Client is not connected.")
        sftp = self.client.open_sftp()
        try:
            self.execute(f"rm -rf {remote_path}")
            def recursive_upload(local_dir, remote_dir):
                self.execute(f"mkdir -p {remote_dir}")
                for item in os.listdir(local_dir):
                    l_path = os.path.join(local_dir, item)
                    r_path = remote_dir + "/" + item
                    if os.path.isdir(l_path):
                        recursive_upload(l_path, r_path)
                    else:
                        sftp.put(l_path, r_path)
            recursive_upload(local_path, remote_path)
        finally:
            sftp.close()

    def close(self):
        """Close connection."""
        if self.client:
            self.client.close()

def wait_for_ssh(ip, timeout=120):
    """Wait for SSH to become available on the target host."""
    start_time = time.time()
    while time.time() - start_time < timeout:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(2)
            s.connect((ip, 22))
            s.close()
            return True
        except Exception:
            time.sleep(2)
    return False

def generate_phx_secret():
    """48 random bytes, base64, no padding characters that would need quoting.

    `secrets` rather than `random`: this signs session cookies, and a predictable value
    means forgeable sessions on the console that administers the cluster.
    """
    import base64
    import secrets

    return base64.b64encode(secrets.token_bytes(48)).decode("ascii").rstrip("=")


def main():
    print("==========================================================")
    print("              Aura HCI Cluster Provisioner                ")
    print("==========================================================")
    
    script_dir = os.path.dirname(os.path.abspath(__file__))
    
    parser = argparse.ArgumentParser(description="Aura HCI Cluster Provisioner")
    parser.add_argument("--force", "-force", action="store_true", 
                        help="Force provisioning even if the hostname format matches Valkyrie-XXXXXX")
    parser.add_argument("--registry", default=None,
                        help="Registry host to pull third-party images from instead of "
                             "docker.io and quay.io, e.g. mirror.local:5000. The "
                             "repository path and tag are preserved. Also settable as "
                             "HELIOS_REGISTRY.")
    args = parser.parse_args()
    force_provision = args.force

    global REGISTRY
    REGISTRY = (args.registry or os.environ.get("HELIOS_REGISTRY") or "").strip()
    if REGISTRY:
        print(f"Pulling third-party images from {REGISTRY} instead of their default registries.")
        for _name in sorted(IMAGES):
            print(f"  {_name}: {resolve_image(_name)}")

    global DEFAULT_PASSWORD, DHCP_IPS, HOSTS, VIP, PREFIX, GATEWAY, PHX_SECRET
    
    DEFAULT_PASSWORD = os.environ.get("HELIOS_PASSWORD")
    if not DEFAULT_PASSWORD:
        import getpass
        try:
            DEFAULT_PASSWORD = getpass.getpass("Enter cluster root password: ").strip()
        except (IOError, NameError):
            DEFAULT_PASSWORD = ""

    dhcp_env = os.environ.get("HELIOS_DHCP_IPS")
    if dhcp_env:
        DHCP_IPS = [ip.strip() for ip in dhcp_env.split(",") if ip.strip()]
    else:
        try:
            dhcp_input = input("Enter current temporary DHCP/dynamic IPs of the nodes (comma separated): ").strip()
            DHCP_IPS = [ip.strip() for ip in dhcp_input.split(",") if ip.strip()]
        except (IOError, NameError):
            DHCP_IPS = []

    hosts_env = os.environ.get("HELIOS_STATIC_IPS")
    if hosts_env:
        HOSTS = [ip.strip() for ip in hosts_env.split(",") if ip.strip()]
    else:
        try:
            hosts_input = input("Enter desired static IP addresses for the nodes (comma separated): ").strip()
            HOSTS = [ip.strip() for ip in hosts_input.split(",") if ip.strip()]
        except (IOError, NameError):
            HOSTS = []

    # Decided here, where HOSTS is settled and before any node is touched.
    PHX_SECRET = generate_phx_secret()

    vip_env = os.environ.get("HELIOS_VIP")
    if vip_env:
        VIP = vip_env.strip()
    else:
        default_vip = ""
        if HOSTS:
            parts = HOSTS[0].split(".")
            if len(parts) == 4:
                parts[3] = "130" if parts[3] != "130" else "131"
                default_vip = ".".join(parts)
        try:
            vip_input = input(f"Enter desired virtual IP (VIP) for the cluster [{default_vip}]: ").strip()
            VIP = vip_input if vip_input else default_vip
        except (IOError, NameError):
            VIP = default_vip

    detected_prefix = ""
    detected_gateway = ""
    
    # Try to connect to the first DHCP IP to query network settings dynamically
    if DHCP_IPS and DEFAULT_PASSWORD:
        try:
            print(f"[*] Attempting to auto-detect network settings from first DHCP node ({DHCP_IPS[0]})...")
            import re
            test_node = RemoteNode(DHCP_IPS[0], DEFAULT_USERNAME, DEFAULT_PASSWORD)
            if test_node.connect(use_key=False):
                rc_addr, addr_out, _ = test_node.execute("ip -o -4 addr show")
                if rc_addr == 0 and addr_out:
                    match_pref = re.search(rf"{re.escape(DHCP_IPS[0])}/([0-9]+)", addr_out)
                    if match_pref:
                        detected_prefix = match_pref.group(1)
                
                rc_gw, gw_out, _ = test_node.execute("ip route show default")
                if rc_gw == 0 and gw_out:
                    match_gw = re.search(r"via\s+([0-9.]+)", gw_out)
                    if match_gw:
                        detected_gateway = match_gw.group(1)
                test_node.close()
                if detected_prefix or detected_gateway:
                    print(f"[*] Auto-detected prefix: /{detected_prefix}, gateway: {detected_gateway}")
                else:
                    print("[*] No active network settings could be auto-detected from the node.")
        except Exception as e:
            print(f"[*] Auto-detection failed: {e}")

    prefix_env = os.environ.get("HELIOS_PREFIX")
    if prefix_env:
        PREFIX = prefix_env.strip()
    else:
        while True:
            try:
                prompt_suffix = f" [{detected_prefix}]" if detected_prefix else ""
                prefix_input = input(f"Enter netmask prefix (e.g. 24, 22){prompt_suffix}: ").strip()
                if prefix_input:
                    PREFIX = prefix_input
                    break
                elif detected_prefix:
                    PREFIX = detected_prefix
                    break
                else:
                    print("[ERROR] Subnet prefix could not be auto-detected. You must enter a value (e.g., 24).")
            except (IOError, NameError, EOFError):
                if detected_prefix:
                    PREFIX = detected_prefix
                    break
                else:
                    print("[ERROR] Non-interactive execution but HELIOS_PREFIX environment variable is not set and auto-detection failed.")
                    sys.exit(1)

    gateway_env = os.environ.get("HELIOS_GATEWAY")
    if gateway_env:
        GATEWAY = gateway_env.strip()
    else:
        while True:
            try:
                prompt_suffix = f" [{detected_gateway}]" if detected_gateway else ""
                gateway_input = input(f"Enter default gateway{prompt_suffix}: ").strip()
                if gateway_input:
                    GATEWAY = gateway_input
                    break
                elif detected_gateway:
                    GATEWAY = detected_gateway
                    break
                else:
                    print("[ERROR] Default gateway could not be auto-detected. You must enter a value (e.g., 10.10.102.1).")
            except (IOError, NameError, EOFError):
                if detected_gateway:
                    GATEWAY = detected_gateway
                    break
                else:
                    print("[ERROR] Non-interactive execution but HELIOS_GATEWAY environment variable is not set and auto-detection failed.")
                    sys.exit(1)

    if not DEFAULT_PASSWORD or not DHCP_IPS or not HOSTS or not VIP or not PREFIX or not GATEWAY:
        print("[ERROR] Provisioning configuration missing. Please set HELIOS_PASSWORD, HELIOS_DHCP_IPS, HELIOS_STATIC_IPS, HELIOS_VIP, HELIOS_PREFIX, and HELIOS_GATEWAY environment variables, or run the script interactively.")
        sys.exit(1)

    priv_key_path = os.path.expanduser("~/.ssh/id_rsa_hci")
    if not os.path.exists(priv_key_path):
        print(f"[*] Private SSH key not found. Generating a new key pair at {priv_key_path}...")
        try:
            os.makedirs(os.path.dirname(priv_key_path), exist_ok=True)
            key = paramiko.RSAKey.generate(2048)
            key.write_private_key_file(priv_key_path)
            with open(priv_key_path + ".pub", "w") as f:
                f.write(f"ssh-rsa {key.get_base64()} root@valkyrie\n")
            print(f"[*] Successfully generated SSH key pair.")
        except Exception as e:
            print(f"[FATAL] Failed to generate SSH key pair: {e}")
            sys.exit(1)
        
    try:
        key = paramiko.RSAKey.from_private_key_file(priv_key_path)
        pub_key_content = f"ssh-rsa {key.get_base64()} root@valkyrie"
    except Exception as e:
        print(f"[FATAL] Failed to load SSH key: {e}")
        sys.exit(1)

    import threading
    import hashlib

    # Thread-safe lists
    nodes_map = {}
    nodes_lock = threading.Lock()

    def provision_single_node(idx, target_ip, dhcp_ip):
        print(f"[{target_ip}] Starting provisioning thread...")
        username = DEFAULT_USERNAME
        password = DEFAULT_PASSWORD
        connected_ip = target_ip
        node = RemoteNode(target_ip, username, password)
        
        # Connect to target_ip or fall back to DHCP IP using password credentials
        if node.connect(use_key=False):
            print(f"[{target_ip}] Connected successfully using password.")
            node.execute("mkdir -p /root/.ssh && chmod 700 /root/.ssh")
            node.execute(f"echo '{pub_key_content}' >> /root/.ssh/authorized_keys")
            node.execute("chmod 600 /root/.ssh/authorized_keys")
        else:
            print(f"[{target_ip}] Target IP not reachable. Connecting to DHCP IP {dhcp_ip}...")
            node = RemoteNode(dhcp_ip, username, password)
            connected_ip = dhcp_ip
            if node.connect(use_key=False):
                print(f"[{dhcp_ip}] Connected successfully using password.")
                node.execute("mkdir -p /root/.ssh && chmod 700 /root/.ssh")
                node.execute(f"echo '{pub_key_content}' >> /root/.ssh/authorized_keys")
                node.execute("chmod 600 /root/.ssh/authorized_keys")
            else:
                print(f"[FATAL] [{target_ip}] Could not connect to either target IP or DHCP IP {dhcp_ip}.")
                return

        # There is no Secure Boot pre-flight any more, and that is worth stating rather
        # than silently dropping. This used to refuse to provision a host with Secure Boot
        # enabled, because DRBD shipped as an out-of-tree kernel module (kmod-drbd9x) that
        # the kernel rejects when the ELRepo key is not enrolled -- taking the whole
        # storage layer down. Sidon is a userspace daemon speaking NBD over a unix socket,
        # so it loads no module, and Secure Boot can simply stay on.

        # NMCLI static IP migration
        if connected_ip != target_ip:
            try:
                rc_net, conn_name, _ = node.execute("nmcli -t -f TYPE,NAME connection show --active | grep -m1 ethernet | cut -d: -f2")
                conn_name = conn_name.strip()
                if rc_net == 0 and conn_name:
                    print(f"[{dhcp_ip}] Configuring connection '{conn_name}' to static target IP {target_ip}/{PREFIX} via gateway {GATEWAY}...")
                    node.execute(f"nmcli connection modify '{conn_name}' ipv4.addresses {target_ip}/{PREFIX} ipv4.gateway {GATEWAY} ipv4.dns '1.1.1.1,8.8.8.8' ipv4.method manual")
                    node.client.exec_command(f"(sleep 1 && nmcli connection up '{conn_name}') &")
                    node.close()
                    print(f"[{dhcp_ip}] IP migration triggered. Waiting 10 seconds...")
                    time.sleep(10)
                    
                    node = RemoteNode(target_ip, username, password)
                    if not node.connect(use_key=False):
                        print(f"[FATAL] [{target_ip}] Failed to connect after static IP migration.")
                        return
                    print(f"[{target_ip}] Reconnected successfully on target static IP.")
            except Exception as e:
                print(f"[{dhcp_ip}] Warning: static IP configuration failed: {e}")

        # Hostname configuration & reboot check
        try:
            host_out = node.execute("hostname")[1].strip()
            h = hashlib.md5(target_ip.encode()).hexdigest()[:6].upper()
            new_hostname = f"Valkyrie-{h}"
            
            if host_out != new_hostname or force_provision:
                print(f"[{target_ip}] Assigning hostname: {new_hostname} (was {host_out})")
                node.execute(f"hostnamectl set-hostname {new_hostname}")
                node.execute(f"grep -q '{new_hostname}' /etc/hosts || echo '127.0.0.1 {new_hostname}' >> /etc/hosts")
                
                try:
                    node.client.exec_command("reboot")
                except Exception:
                    pass
                node.close()
                print(f"[{target_ip}] Rebooting. Waiting 15 seconds...")
                time.sleep(15)
                if not wait_for_ssh(target_ip):
                    print(f"[FATAL] [{target_ip}] Node did not boot back online after hostname change.")
                    return
                
                node = RemoteNode(target_ip, username, password)
                if not node.connect(use_key=False):
                    print(f"[FATAL] [{target_ip}] Failed to reconnect after reboot.")
                    return
            else:
                print(f"[{target_ip}] Hostname is already correct: {host_out}")
        except Exception as e:
            print(f"[{target_ip}] Hostname assignment failed: {e}")
            node.close()
            return

        # Phase 2: Host Package Installation & Directory Setup
        try:
            print(f"[{node.ip}] Installing repositories and packages (dnf-plugins-core, ELRepo, openssl, podman, qemu, libvirt, nfs, lvm2)...")
            dnf_cmds = [
                "rm -f /etc/yum.repos.d/*elrepo-release-10*.repo || true",
                "dnf install -y --nogpgcheck dnf-plugins-core || true",
                "dnf install -y --nogpgcheck https://www.elrepo.org/elrepo-release-10.el10.elrepo.noarch.rpm || true",
                "dnf install -y --nogpgcheck openssl podman qemu-kvm libvirt nfs-utils lvm2 iproute grep cargo clang lld ipmitool"
            ]
            for cmd in dnf_cmds:
                node.execute(cmd, check_exit=True)

            print(f"[{node.ip}] Enabling KVM ignore_msrs for nested virtualization stability...")
            node.execute("echo 'options kvm ignore_msrs=Y' > /etc/modprobe.d/kvm.conf")
            node.execute("modprobe -r kvm_intel || true")
            node.execute("modprobe -r kvm || true")
            node.execute("modprobe kvm || true")
            node.execute("modprobe kvm_intel || true")

            print(f"[{node.ip}] Starting systemd services (podman, libvirtd, virtqemud, virtnetworkd)...")
            for svc in ["podman", "libvirtd", "virtqemud", "virtnetworkd"]:
                node.execute(f"systemctl enable {svc} && systemctl start {svc}")

            print(f"[{node.ip}] Configuring firewalld rules...")
            try:
                node.execute("systemctl stop firewalld && systemctl disable firewalld")
            except Exception as e:
                print(f"[{node.ip}] Warning: firewalld setup failed: {e}")

            print(f"[{node.ip}] Creating host storage mount directories...")
            node.execute("mkdir -p /var/lib/hci/zookeeper/data /var/lib/hci/zookeeper/log "
                         "/var/lib/hci/hydra/data /run/hci "
                         "/etc/hci/spectrum/certs /etc/hci/slate /var/lib/hci/aether/volumes "
                         "/var/lib/hci/images")
        except Exception as e:
            print(f"[{node.ip}] Package/Directory setup failed: {e}")
            node.close()
            return

        # Phase 3: Synchronizing Configuration Files
        try:
            print(f"[{node.ip}] Syncing configurations & keys...")
            with open(priv_key_path, "r", encoding="utf-8") as f:
                local_priv_key = f.read()
            with open(priv_key_path + ".pub", "r", encoding="utf-8") as f:
                local_pub_key = f.read()
            node.write_file("/root/.ssh/id_rsa", local_priv_key)
            node.write_file("/root/.ssh/id_rsa.pub", local_pub_key)
            node.execute("chmod 600 /root/.ssh/id_rsa")

            # Copy binaries
            node.write_file("/usr/local/bin/spark", base64.b64decode(SPARK_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/spark")

            node.write_file("/usr/local/bin/cluster", base64.b64decode(CLUSTER_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/cluster")

            node.write_file("/usr/local/bin/spark-daemon", base64.b64decode(SPARK_DAEMON_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/spark-daemon")

            spark_svc = '''[Unit]
Description=Spark Host Management Daemon
After=network.target

[Service]
Type=simple
ExecStart=/usr/local/bin/spark-daemon
Restart=always
RestartSec=3
User=root
CPUWeight=200
MemoryMax=512M
MemoryHigh=400M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/spark-daemon.service", spark_svc)
            node.execute("systemctl daemon-reload && systemctl enable spark-daemon")

            # Deploy Bifrost Daemon
            node.write_file("/usr/local/bin/bifrost", base64.b64decode(BIFROST_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/bifrost")

            bifrost_svc = '''[Unit]
Description=Bifrost VM Lifecycle Management Service
After=zookeeper.service
ConditionPathExists=/etc/hci/cluster.json
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/bifrost
Restart=always
RestartSec=3
User=root
CPUWeight=100
MemoryMax=512M
MemoryHigh=400M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/bifrost.service", bifrost_svc)
            node.execute("systemctl daemon-reload && systemctl enable bifrost")

            # Deploy Dagur task scheduler
            node.write_file("/usr/local/bin/dagur", base64.b64decode(DAGUR_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/dagur")
            
            dagur_svc = '''[Unit]
Description=Dagur HA Task Scheduler Service
After=zookeeper.service
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/dagur
Restart=always
RestartSec=3
User=root
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/dagur.service", dagur_svc)
            node.execute("systemctl daemon-reload && systemctl enable dagur")

            # Deploy Mimir Daemon
            node.write_file("/usr/local/bin/mimir", base64.b64decode(MIMIR_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/mimir")

            # Deploy mcli and mcli-runner
            node.write_file("/usr/local/bin/mcli", base64.b64decode(MCLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/mcli")
            node.write_file("/usr/local/bin/mcli-runner", base64.b64decode(MCLI_RUNNER_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/mcli-runner")
            node.write_file("/usr/local/bin/allssh", base64.b64decode(ALLSSH_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/allssh")

            mimir_svc = '''[Unit]
Description=Mimir Health Check and Diagnostics Daemon
After=zookeeper.service
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/mimir
Restart=always
RestartSec=3
User=root
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/mimir.service", mimir_svc)
            node.execute("systemctl daemon-reload && systemctl enable mimir")

            # Deploy Vali Daemon
            node.write_file("/usr/local/bin/vali", base64.b64decode(VALI_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/vali")

            vali_svc = '''[Unit]
Description=Vali Audit Log and Compliance Daemon
After=zookeeper.service
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/vali
Restart=always
RestartSec=3
User=root
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/vali.service", vali_svc)
            node.execute("systemctl daemon-reload && systemctl enable vali")

            # Deploy Gatoway Daemon
            node.write_file("/usr/local/bin/gatoway", base64.b64decode(GATOWAY_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/gatoway")

            gatoway_svc = '''[Unit]
Description=Gatoway L2 Network Sync Daemon
After=zookeeper.service
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/gatoway
Restart=always
RestartSec=3
User=root
Environment=PYTHONUNBUFFERED=1
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/gatoway.service", gatoway_svc)
            node.execute("systemctl daemon-reload && systemctl enable gatoway")

            # Deploy Urbosa Daemon
            node.write_file("/usr/local/bin/urbosa", base64.b64decode(URBOSA_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/urbosa")

            urbosa_svc = '''[Unit]
Description=Urbosa SDN Logical Router and Overlay Orchestrator
After=zookeeper.service
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/urbosa
Restart=always
RestartSec=3
User=root
Environment=PYTHONUNBUFFERED=1
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/urbosa.service", urbosa_svc)
            node.execute("systemctl daemon-reload && systemctl enable urbosa")

            # Deploy Logos Daemon
            node.write_file("/usr/local/bin/logos", base64.b64decode(LOGOS_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/logos")

            logos_svc = '''[Unit]
Description=Logos Distributed Metrics Service
After=zookeeper.service
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/logos
Restart=always
RestartSec=3
User=root
Environment=PYTHONUNBUFFERED=1
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/logos.service", logos_svc)
            node.execute("systemctl daemon-reload && systemctl enable logos")

            # Deploy Mipha Daemon
            node.write_file("/usr/local/bin/mipha", base64.b64decode(MIPHA_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/mipha")

            mipha_svc = '''[Unit]
Description=Mipha HA Cluster Monitor Daemon
After=zookeeper.service
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/mipha
Restart=always
RestartSec=3
User=root
Environment=PYTHONUNBUFFERED=1
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/mipha.service", mipha_svc)
            node.execute("systemctl daemon-reload && systemctl enable mipha")

            # Deploy Urbosa Bootstrap Script
            urbosa_bootstrap_script = base64.b64decode(URBOSA_BOOTSTRAP_B64).decode('utf-8')
            node.write_file("/usr/local/bin/urbosa-bootstrap", urbosa_bootstrap_script)
            node.execute("chmod +x /usr/local/bin/urbosa-bootstrap")

            # Deploy Daruk Proxy
            daruk_script = base64.b64decode(DARUK_B64).decode('utf-8')
            node.write_file("/usr/local/bin/daruk.py", daruk_script)
            node.write_file("/var/lib/hci/hydra/data/daruk.py", daruk_script)

            daruk_svc = """[Unit]
Description=Daruk Database Query Proxy Service
After=hydra-db.service
Requires=hydra-db.service

[Service]
Type=simple
# The proxy executes the copy inside the DB volume, but LCM upgrades only replace
# /usr/local/bin/daruk.py. Refresh it on every start so a fast-patch plus a restart
# actually runs the new code instead of silently re-running the old copy.
ExecStartPre=-/usr/bin/cp -f /usr/local/bin/daruk.py /var/lib/hci/hydra/data/daruk.py
ExecStartPre=-/usr/bin/podman exec systemd-hydra-db pkill -f daruk.py
ExecStart=/usr/bin/podman exec systemd-hydra-db python3 /var/lib/scylla/daruk.py
Restart=always
RestartSec=3
User=root
Environment=PYTHONUNBUFFERED=1

[Install]
WantedBy=multi-user.target
"""
            node.write_file("/etc/systemd/system/daruk.service", daruk_svc)
            node.execute("systemctl daemon-reload && systemctl enable daruk")

            # Deploy Catalyst Daemon
            node.write_file("/usr/local/bin/catalyst", base64.b64decode(CATALYST_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/catalyst")

            catalyst_svc = '''[Unit]
Description=Catalyst API Gateway Daemon
After=zookeeper.service
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/catalyst
Restart=always
RestartSec=3
User=root
Environment=PYTHONUNBUFFERED=1
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/catalyst.service", catalyst_svc)
            node.execute("systemctl daemon-reload && systemctl enable catalyst")

            # Deploy Hylia Daemon
            yggdrasil_cli = base64.b64decode(HYLIA_B64).decode('utf-8')
            node.write_file("/usr/local/bin/hylia", yggdrasil_cli)
            node.execute("chmod +x /usr/local/bin/hylia")

            # Deploy Lanayru guest-Kubernetes engine. Not a daemon and has no systemd
            # unit: spectrum_server imports it as a module, so it only needs to exist on
            # disk and inside the Spectrum image (see the build context below).
            node.write_file("/usr/local/bin/lanayru.py", base64.b64decode(LANAYRU_B64).decode('utf-8'))

            # Shared minimal ZooKeeper client, imported by spark-daemon and the cluster CLI.
            node.write_file("/usr/local/bin/helios_zk.py", base64.b64decode(HELIOS_ZK_B64).decode('utf-8'))
            # Update signature verification, imported by check-updates and hylia.
            node.write_file("/usr/local/bin/helios_sig.py", base64.b64decode(HELIOS_SIG_B64).decode('utf-8'))
            # spark-daemon imports this to reach Sidon's control socket; Spectrum gets
            # its own copy in the image below, because it calls the same operations
            # through spark rather than touching the socket itself.
            node.write_file("/usr/local/bin/helios_sidon.py", base64.b64decode(HELIOS_SIDON_B64).decode('utf-8'))

            # The ordered schema, imported by every daemon that used to carry its own
            # CREATE TABLE statements. Deployed before them, since they call into it
            # at startup.
            node.write_file("/usr/local/bin/helios_schema.py", base64.b64decode(HELIOS_SCHEMA_B64).decode('utf-8'))

            yggdrasil_svc = '''[Unit]
Description=Hylia Rolling Upgrade and Life Cycle Manager
After=zookeeper.service

[Service]
Type=simple
ExecStart=/usr/local/bin/hylia
Restart=always
RestartSec=5
User=root
Environment=PYTHONUNBUFFERED=1
CPUWeight=100
MemoryMax=256M
MemoryHigh=200M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/hylia.service", yggdrasil_svc)
            node.execute("systemctl daemon-reload && systemctl enable hylia")

            # CLI helpers
            node.write_file("/usr/local/bin/catcli", base64.b64decode(CATCLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/catcli")

            node.write_file("/usr/local/bin/check-updates", base64.b64decode(CHECK_UPDATES_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/check-updates")

            # Certificate lifecycle: status, renewal, CA rotation. Driven over SSH rather
            # than mTLS on purpose -- it has to work once the certificates it repairs have
            # already expired, which is exactly when port 9099 is what is broken.
            node.write_file("/usr/local/bin/impa", base64.b64decode(IMPA_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/impa")

            # Metadata backup and restore. The keyspace is the only statement of which
            # extent group holds which part of which vdisk -- the extents survive a node
            # loss and mean nothing without the map.
            node.write_file("/usr/local/bin/saga", base64.b64decode(SAGA_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/saga")

            # /etc/hci is already bind-mounted read-only into the Spectrum container, so
            # host daemons and the console verify against one file rather than two that
            # can drift. 0644: it is a public key, and every daemon has to read it.
            if "PRIVATE KEY" in RELEASE_PUBKEY_PEM:
                raise SystemExit(
                    "RELEASE_PUBKEY_PEM contains a PRIVATE KEY. Provisioning would copy "
                    "the update signing key onto every node in the cluster. Paste the "
                    "output of `openssl pkey -pubout` instead.")
            if RELEASE_PUBKEY_PEM.strip():
                node.execute("mkdir -p /etc/hci/keys && chmod 755 /etc/hci/keys")
                node.write_file("/etc/hci/keys/release_ed25519.pub", RELEASE_PUBKEY_PEM)
                node.execute("chmod 644 /etc/hci/keys/release_ed25519.pub")
            else:
                print(f"[{node.ip}] WARNING: RELEASE_PUBKEY_PEM is empty. Update checks "
                      f"will fail closed until a release key is pinned -- see "
                      f"docs/update_signing.md. Nothing else is affected.")

            # Fencing configuration. Created on every host, not just the leader: Mipha's
            # failover loop only runs on the ZooKeeper leader and leadership moves, so
            # the node that ends up fencing is not knowable in advance.
            #
            # Deliberately a file and not a hydra table. A fence is needed precisely when
            # things have failed, and the database is often part of what failed -- the
            # same chicken-and-egg that made the old fence useless. It is also 0600 root:
            # anything in hydra is readable by the web tier, and these are BMC passwords.
            #
            # Absent is safe: no BMC entry means that rung of the ladder reports why it
            # cannot run and the ladder falls through to storage fencing.
            node.execute("mkdir -p /etc/hci/fencing.d && chmod 700 /etc/hci/fencing.d")
            node.execute("test -f /etc/hci/fencing.json || "
                         "printf '%s\n' '{\"bmc\": {}}' > /etc/hci/fencing.json")
            node.execute("chmod 600 /etc/hci/fencing.json && chown root:root /etc/hci/fencing.json")

            # nodetool host wrapper — proxies into the hydra-db ScyllaDB container
            node.write_file("/usr/local/bin/nodetool", base64.b64decode(NODETOOL_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/nodetool")

            node.write_file("/usr/local/bin/valcli", base64.b64decode(VALCLI_CLI_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/valcli")

            node.write_file("/usr/local/bin/urbosa-bootstrap", base64.b64decode(URBOSA_BOOTSTRAP_B64).decode('utf-8'))
            node.execute("chmod +x /usr/local/bin/urbosa-bootstrap")

            # Daruk files
            node.write_file("/usr/local/bin/daruk.py", base64.b64decode(DARUK_B64).decode('utf-8'))
            node.write_file("/var/lib/hci/hydra/data/daruk.py", base64.b64decode(DARUK_B64).decode('utf-8'))

            daruk_svc = '''[Unit]
Description=Daruk Database Query Proxy Service
After=hydra-db.service
Requires=hydra-db.service

[Service]
Type=simple
# The proxy executes the copy inside the DB volume, but LCM upgrades only replace
# /usr/local/bin/daruk.py. Refresh it on every start so a fast-patch plus a restart
# actually runs the new code instead of silently re-running the old copy.
ExecStartPre=-/usr/bin/cp -f /usr/local/bin/daruk.py /var/lib/hci/hydra/data/daruk.py
ExecStartPre=-/usr/bin/podman exec systemd-hydra-db pkill -f daruk.py
ExecStart=/usr/bin/podman exec systemd-hydra-db python3 /var/lib/scylla/daruk.py
Restart=always
RestartSec=3
User=root
Environment=PYTHONUNBUFFERED=1

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/daruk.service", daruk_svc)

            # Static configurations resolution
            zoo_servers_parts = []
            for i, ip in enumerate(HOSTS, start=1):
                if i > 3:
                    zoo_servers_parts.append(f"server.{i}={ip}:2888:3888:observer;2181")
                else:
                    zoo_servers_parts.append(f"server.{i}={ip}:2888:3888;2181")
            zoo_servers_str = " ".join(zoo_servers_parts)
            seed_ips = HOSTS[0]

            # Generate cluster.json
            cluster_json_data = {
                "cluster_name": "hci-01",
                "redundancy_factor": 1,
                "dfs_engine": "sidon",
                "vip": VIP,
                "hosts": []
            }
            for i, ip in enumerate(HOSTS, start=1):
                cluster_json_data["hosts"].append({
                    "node_id": i,
                    "ip": ip,
                    "hostname": f"Valkyrie-{hashlib.md5(ip.encode()).hexdigest()[:6].upper()}"
                })
            cluster_json_str = json.dumps(cluster_json_data, indent=4)
            node.write_file("/etc/hci/cluster.json", cluster_json_str)

            # No storage-pools.json. It described LINSTOR's view of the disks -- a pool
            # name, a thin pool, a volume group -- and Sidon has none of that: it writes
            # extent groups as files onto one filesystem, and where that filesystem lives
            # is decided by the mount, not by a configuration file.

            node.write_file("/etc/hci/zookeeper/myid", str(idx))

            spectrum_env = f"SPECTRUM_HOST={node.ip}\nSPECTRUM_PORT=8000\nSPECTRUM_LOG_LEVEL=info\n"
            node.write_file("/etc/hci/spectrum/spectrum.env", spectrum_env)

            # The Phoenix console's environment. Same secret on every node, this node's
            # own address as PHX_HOST, and every node as an accepted origin because Slate
            # can route a request to any of them.
            if PHX_SECRET:
                phx_env = (
                    f"SECRET_KEY_BASE={PHX_SECRET}\n"
                    f"PHX_HOST={node.ip}\n"
                    f"PHX_EXTRA_ORIGINS={','.join(HOSTS)}\n"
                )
                node.write_file("/etc/hci/spectrum/spectrum-phx.env", phx_env)
                node.execute("chmod 600 /etc/hci/spectrum/spectrum-phx.env")

            hydra_env = f"HYDRA_DB_SEEDS={seed_ips}\nHYDRA_DB_LISTEN={node.ip}\n"
            node.write_file("/etc/hci/hydra/cassandra.env", hydra_env)

            # Traefik (Slate) config files
            with open(os.path.join(script_dir, "slate_config", "traefik.yml"), "r", encoding="utf-8") as f_yml:
                slate_yml_content = f_yml.read()
            with open(os.path.join(script_dir, "slate_config", "dynamic.yml"), "r", encoding="utf-8") as f_dyn:
                dynamic_yml_content = f_dyn.read()

            node.write_file("/etc/hci/slate/traefik.yml", slate_yml_content)
            node.write_file("/etc/hci/slate/dynamic.yml", dynamic_yml_content)

            # Deploy Agahnim Console Proxy (Rust)
            print(f"[{node.ip}] Deploying and compiling Agahnim console proxy...")
            node.execute("rm -rf /tmp/agahnim_build && mkdir -p /tmp/agahnim_build")
            agahnim_local_dir = os.path.join(script_dir, "agahnim")
            node.upload_directory(agahnim_local_dir, "/tmp/agahnim_build")
            node.execute("cd /tmp/agahnim_build && cargo build --release", check_exit=True)
            node.execute("cp /tmp/agahnim_build/target/release/agahnim /usr/local/bin/agahnim", check_exit=True)
            node.execute("chmod +x /usr/local/bin/agahnim", check_exit=True)
            node.execute("rm -rf /tmp/agahnim_build")

            agahnim_svc = '''[Unit]
Description=Agahnim Console Proxy Daemon
After=network.target
ConditionPathExists=/etc/hci/cluster.json
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
ExecStart=/usr/local/bin/agahnim 8081
Restart=always
RestartSec=3
User=root
CPUWeight=100
MemoryMax=256M

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/agahnim.service", agahnim_svc)
            node.execute("systemctl daemon-reload && systemctl enable agahnim && systemctl restart agahnim", check_exit=True)

            # Deploy Sidon (extent-based DFS data path, Rust). Same shape as Agahnim:
            # source is uploaded and compiled on the node, because a Rust binary built
            # elsewhere would carry this repo's glibc rather than the node's.
            print(f"[{node.ip}] Deploying and compiling Sidon data-path daemon...")
            node.execute("rm -rf /tmp/sidon_build && mkdir -p /tmp/sidon_build")
            node.upload_directory(os.path.join(script_dir, "sidon"), "/tmp/sidon_build")
            node.execute("cd /tmp/sidon_build && cargo build --release", check_exit=True)
            node.execute("cp /tmp/sidon_build/target/release/sidon /usr/local/bin/sidon", check_exit=True)
            node.execute("chmod +x /usr/local/bin/sidon", check_exit=True)
            node.execute("rm -rf /tmp/sidon_build")
            # The qemu group owns the NBD socket directory: libvirt runs qemu as that
            # user, and it must be able to open a vdisk's socket without the sockets
            # being world-accessible.
            # Sidon gets its own thin LV rather than sharing the root filesystem. Three
            # reasons, and none of them is tidiness: a full extent store must not be able
            # to wedge the host, dm-flakey needs a device of its own to sit under, and the
            # design says egroups live on a thin LV in vg_aether. The pool already owns the
            # whole VG, so this is carved from inside it and costs nothing until used.
            node.execute(
                "lvs vg_aether/sidon >/dev/null 2>&1 || "
                "lvcreate -y -V 150G --thinpool thin_pool_aether -n sidon vg_aether",
                check_exit=True)
            node.execute("blkid /dev/vg_aether/sidon >/dev/null 2>&1 || mkfs.xfs -q /dev/vg_aether/sidon",
                         check_exit=True)
            node.execute("mkdir -p /var/lib/hci/sidon")
            # By UUID, with nofail and a device timeout.
            #
            # A raw device path plus the default options means a host whose storage volume
            # is missing or slow to appear stops at the emergency shell instead of booting.
            # That turns a recoverable storage problem into a host that cannot even be
            # reached to fix it -- and mimir's fstab check refuses this entry without them,
            # which is how the omission was caught.
            node.execute(
                "grep -q ' /var/lib/hci/sidon ' /etc/fstab || "
                "echo \"UUID=$(blkid -s UUID -o value /dev/vg_aether/sidon) "
                "/var/lib/hci/sidon xfs "
                "defaults,noatime,nofail,x-systemd.device-timeout=5s 0 0\" >> /etc/fstab",
                check_exit=True)
            node.execute("mountpoint -q /var/lib/hci/sidon || mount /var/lib/hci/sidon", check_exit=True)
            node.execute("mkdir -p /var/lib/hci/sidon/journal /var/lib/hci/sidon/egroups /var/lib/hci/sidon/nbd")
            node.execute("chgrp -R qemu /var/lib/hci/sidon/nbd && chmod 0750 /var/lib/hci/sidon/nbd")

            sidon_svc = '''[Unit]
Description=Sidon DFS Data Path Daemon
After=network.target daruk.service
Wants=daruk.service
ConditionPathExists=/etc/hci/cluster.json
ConditionPathExists=!/etc/hci/maintenance.state

[Service]
Type=simple
# No port is opened. Control arrives on a unix socket from spark-daemon, which has
# already authenticated the caller over mutual TLS on 9099, and guests attach over a
# per-vdisk unix socket. Adding a storage tier adds no new authenticated surface.
RuntimeDirectory=sidon
RuntimeDirectoryMode=0755
Environment=SIDON_ROOT=/var/lib/hci/sidon
Environment=SIDON_CONTROL=/run/sidon/control.sock
Environment=SIDON_DARUK=127.0.0.1:9043
ExecStart=/usr/local/bin/sidon
Restart=always
RestartSec=3
User=root
CPUWeight=200
MemoryMax=1G

[Install]
WantedBy=multi-user.target
'''
            node.write_file("/etc/systemd/system/sidon.service", sidon_svc)
            node.execute("systemctl daemon-reload && systemctl enable sidon && systemctl restart sidon", check_exit=True)

            # Build Spectrum Container Image
            print(f"[{node.ip}] Building Spectrum web UI container image...")
            node.execute("rm -rf /tmp/spectrum_build && mkdir -p /tmp/spectrum_build/static")
            node.write_file("/tmp/spectrum_build/spectrum_server.py", base64.b64decode(SPECTRUM_SERVER_B64).decode('utf-8'))
            node.write_file("/tmp/spectrum_build/Dockerfile", base64.b64decode(SPECTRUM_DOCKERFILE_B64).decode('utf-8'))
            node.write_file("/tmp/spectrum_build/hylia.py", base64.b64decode(HYLIA_B64).decode('utf-8'))
            node.write_file("/tmp/spectrum_build/lanayru.py", base64.b64decode(LANAYRU_B64).decode('utf-8'))
            node.write_file("/tmp/spectrum_build/helios_zk.py", base64.b64decode(HELIOS_ZK_B64).decode('utf-8'))
            # The image's load_schema_module() looks for these at /app; without them a
            # rebuilt container applies no migrations and cannot verify a release.
            node.write_file("/tmp/spectrum_build/helios_schema.py", base64.b64decode(HELIOS_SCHEMA_B64).decode('utf-8'))
            node.write_file("/tmp/spectrum_build/helios_sig.py", base64.b64decode(HELIOS_SIG_B64).decode('utf-8'))
            node.write_file("/tmp/spectrum_build/helios_sidon.py", base64.b64decode(HELIOS_SIDON_B64).decode('utf-8'))
            node.upload_directory(os.path.join(script_dir, "static"), "/tmp/spectrum_build/static")

            # Compile WebAssembly SPICE LZ decompressor
            print(f"[{node.ip}] Compiling WebAssembly SPICE LZ decompressor...")
            node.execute("cd /tmp/spectrum_build/static/spice-webassembly && make || true")

            node.execute("cd /tmp/spectrum_build && podman build -t spectrum:latest .", check_exit=True)
            # Copy to /usr/local/bin/ for future rolling upgrades
            node.execute("mkdir -p /usr/local/bin/static && cp -rf /tmp/spectrum_build/static/* /usr/local/bin/static/ && cp -f /tmp/spectrum_build/Dockerfile /usr/local/bin/Dockerfile && cp -f /tmp/spectrum_build/spectrum_server.py /usr/local/bin/spectrum_server && chmod +x /usr/local/bin/spectrum_server")
            node.execute("rm -rf /tmp/spectrum_build")
        except Exception as e:
            print(f"[{node.ip}] Config synchronization failed: {e}")
            node.close()
            return

        # Phase 4: Deploying Podman Quadlets
        try:
            print(f"[{node.ip}] Writing Quadlet containers...")
            peer_type_str = " ZOO_PEER_TYPE=observer" if idx > 3 else ""
            zoo_quad = QUADLETS["zookeeper"].format(
                node_id=idx, zoo_servers=zoo_servers_str, peer_type=peer_type_str,
                image=resolve_image("zookeeper"))
            db_quad = QUADLETS["hydra-db"].format(
                seeds=seed_ips, node_ip=node.ip, image=resolve_image("hydra-db"))
            spec_quad = QUADLETS["spectrum"]
            
            node.write_file("/etc/containers/systemd/zookeeper.container", zoo_quad)
            node.write_file("/etc/containers/systemd/hydra-db.container", db_quad)
            node.write_file("/etc/containers/systemd/spectrum.container", spec_quad)
            
            slate_quad = QUADLETS["slate"].format(image=resolve_image("slate"))
            node.write_file("/etc/containers/systemd/slate.container", slate_quad)
            
            # Remove stale Quadlets. spark/odin are legacy names; the rest are from the
            # abandoned Quadlet migration (75b3203) that pointed 11 services at a
            # localhost/helios-base image no commit ever built. They are native units
            # again, so any leftover .container here would generate a conflicting unit.
            stale_quadlets = ["spark", "odin", "spark-daemon", "bifrost", "dagur", "mimir", "vali",
                              "gatoway", "urbosa", "logos", "mipha", "catalyst", "hylia",
                              # The storage tier that used to live here. A node upgraded
                              # from a DRBD cluster still has these on disk, and a leftover
                              # .container generates a unit that starts a satellite against
                              # a controller which no longer exists.
                              "aether", "linstor-controller"]
            node.execute("rm -f " + " ".join(f"/etc/containers/systemd/{q}.container" for q in stale_quadlets))
            node.execute("systemctl daemon-reload")
            # Unlinking the Quadlet does not stop a container that is already running --
            # the generated unit is gone at the next reload, and the container survives
            # until the host reboots. A node upgraded from a DRBD cluster therefore kept
            # a LINSTOR satellite and controller alive for days after every trace of
            # LINSTOR had been removed from the tree.
            node.execute(
                "systemctl stop aether linstor-controller 2>/dev/null; "
                "podman rm -f systemd-aether systemd-linstor-controller 2>/dev/null; "
                "systemctl reset-failed aether linstor-controller 2>/dev/null; true")
            # And the kernel side, which the Quadlets never touched: resources still
            # up, /dev/drbd* still present, /var/lib/linstor still mounted, the module
            # still loaded and the packages still installed. Not forced at any step --
            # `drbdadm down` refusing a resource something has open is the guard, not
            # an obstacle.
            node.execute(DRBD_TEARDOWN)
            # Label the nvram directory before any guest is ever defined here, so the
            # first VM delete on an Enforcing host does not trip over it.
            node.execute(NVRAM_SELINUX)
        except Exception as e:
            print(f"[{node.ip}] Quadlet deployment failed: {e}")
            node.close()
            return

        # Phase 5: Starting Core Platform Services
        try:
            print(f"[{node.ip}] Activating services via systemd...")
            services = ["zookeeper", "hydra-db", "slate"]
            for svc in services:
                try:
                    node.execute(f"systemctl start {svc}")
                except Exception as e:
                    print(f"[{node.ip}] Warning: service '{svc}' failed to start: {e}")

            time.sleep(2)
            try:
                _, out, _ = node.execute("podman ps --format '{{.Names}}'")
                active_list = out.replace('\n', ', ')
                print(f"[{node.ip}] Active containers: {active_list}")
            except Exception as e:
                print(f"[{node.ip}] Container check failed: {e}")
        except Exception as e:
            print(f"[{node.ip}] Activation failed: {e}")
            node.close()
            return

        with nodes_lock:
            nodes_map[target_ip] = node

    # Start provisioning on all hosts in parallel
    threads = []
    for idx, target_ip in enumerate(HOSTS, start=1):
        dhcp_ip = DHCP_IPS[idx - 1]
        t = threading.Thread(target=provision_single_node, args=(idx, target_ip, dhcp_ip))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    # Reconstruct the nodes list in correct order
    nodes = []
    for ip in HOSTS:
        if ip in nodes_map:
            nodes.append(nodes_map[ip])

    if len(nodes) != len(HOSTS):
        print("[FATAL] One or more nodes failed to provision.")
        sys.exit(1)

    # Phase 6: Certificate Generation on Node 1 (sequential/leader-only)
    node1 = nodes[0]
    print(f"\n[{node1.ip}] Generating mTLS and WebUI SSL certificates locally...")
    
    cert_gen_sh = f"""#!/bin/bash
mkdir -p /var/lib/hci/certs_staging && chmod 700 /var/lib/hci/certs_staging
cd /var/lib/hci/certs_staging

# 1. CA
openssl genrsa -out ca.key 2048
# The CA outlives the leaves it signs, deliberately. At 3650 days for both, the CA and
# every node certificate expired on the same day -- and a leaf renewed near that date
# gets a notAfter past its issuer's, verifies fine on the day it is issued, and takes the
# whole cluster down when the CA lapses under it. `impa` refuses to sign such a leaf.
openssl req -new -x509 -days 7300 -key ca.key -out ca.crt -subj "/CN=HCI-Root-CA"

# 2. Client
openssl genrsa -out client.key 2048
cat <<EOF > client.cnf
[req]
distinguished_name = req_distinguished_name
req_extensions = v3_req
prompt = no
[req_distinguished_name]
CN = HCI-Client
[v3_req]
basicConstraints = critical,CA:FALSE
keyUsage = critical,digitalSignature,keyEncipherment
# clientAuth only. This key sits on every node; signed with no extensions it was valid
# for any purpose, so a copy of it could stand up a listener impersonating a node.
extendedKeyUsage = clientAuth
EOF
openssl req -new -key client.key -out client.csr -config client.cnf
openssl x509 -req -days 3650 -in client.csr -CA ca.crt -CAkey ca.key -CAcreateserial -out client.crt -extensions v3_req -extfile client.cnf

# 3. Node certs
for ip in {" ".join(HOSTS)}; do
  # Recomputed per node: the hostname is derived from the IP the same way the Python
  # side derives it (md5 of the address, first six hex digits, upper-cased).
  h=$(printf %s "$ip" | md5sum | cut -c1-6 | tr a-z A-Z)
  cat <<EOF > "node-$ip.cnf"
[req]
distinguished_name = req_distinguished_name
req_extensions = v3_req
prompt = no
[req_distinguished_name]
CN = $ip
[v3_req]
basicConstraints = critical,CA:FALSE
keyUsage = critical,digitalSignature,keyEncipherment
# Both purposes: spark-daemon and mipha dial peers using the node cert, and a server
# verifying its peer applies the ssl_client purpose to it.
extendedKeyUsage = serverAuth,clientAuth
# Every address a caller can legitimately reach this node by. Without these, hostname
# verification cannot be enabled at all and any cluster-signed cert impersonates any
# node. The VIP term is conditional -- an empty SAN component makes `openssl req` fail.
subjectAltName = IP:$ip,IP:127.0.0.1,DNS:localhost,DNS:Valkyrie-$h{f",IP:{VIP}" if VIP else ""}
EOF
  openssl genrsa -out "node-$ip.key" 2048
  openssl req -new -key "node-$ip.key" -out "node-$ip.csr" -config "node-$ip.cnf"
  openssl x509 -req -days 3650 -in "node-$ip.csr" -CA ca.crt -CAkey ca.key -CAcreateserial -out "node-$ip.crt" -extensions v3_req -extfile "node-$ip.cnf"
done

# 4. Shared SSL Certificate for WebUI/Traefik (Slate)
mkdir -p /etc/hci/spectrum/certs
if [ ! -f /etc/hci/spectrum/certs/server.crt ] || [ ! -f /etc/hci/spectrum/certs/server.key ]; then
  openssl req -x509 -nodes -newkey rsa:2048 -keyout /etc/hci/spectrum/certs/server.key -out /etc/hci/spectrum/certs/server.crt -days 3650 -subj '/CN=Spectrum'
fi

chmod 600 *.key
"""
    node1.write_file("/tmp/gen_certs.sh", cert_gen_sh)
    node1.execute("chmod +x /tmp/gen_certs.sh && /tmp/gen_certs.sh && rm -f /tmp/gen_certs.sh", check_exit=True)
    print(f"[{node1.ip}] mTLS and WebUI SSL certificates generated successfully.")

    # Read the generated certificates from node1
    _, ca_crt, _ = node1.execute("cat /var/lib/hci/certs_staging/ca.crt")
    _, client_crt, _ = node1.execute("cat /var/lib/hci/certs_staging/client.crt")
    _, client_key, _ = node1.execute("cat /var/lib/hci/certs_staging/client.key")
    _, shared_ssl_crt, _ = node1.execute("cat /etc/hci/spectrum/certs/server.crt")
    _, shared_ssl_key, _ = node1.execute("cat /etc/hci/spectrum/certs/server.key")

    # Collect SSH host keys from all nodes to seed /root/.ssh/known_hosts securely
    import hashlib
    all_targets = []
    for ip in HOSTS:
        all_targets.append(ip)
        h = hashlib.md5(ip.encode()).hexdigest()[:6].upper()
        all_targets.append(f"Valkyrie-{h}")
    targets_str = " ".join(all_targets)
    
    print(f"\n[{node1.ip}] Collecting SSH host keys using ssh-keyscan...")
    _, known_hosts_content, _ = node1.execute(f"ssh-keyscan -H {targets_str} 2>/dev/null")

    # Phase 7: Distribute certificates to all nodes in parallel
    print("\n--- Phase 7: Distributing Certificates & Starting Daemons ---")
    def distribute_certs(node):
        print(f"[{node.ip}] Distributing mTLS certificates...")
        node.execute("mkdir -p /root/.certs /etc/hci/spark/certs")
        
        node.write_file("/root/.certs/ca.crt", ca_crt)
        node.write_file("/root/.certs/client.crt", client_crt)
        node.write_file("/root/.certs/client.key", client_key)
        node.execute("chmod 600 /root/.certs/client.key")

        print(f"[{node.ip}] Seeding SSH known_hosts...")
        node.write_file("/root/.ssh/known_hosts", known_hosts_content)
        node.execute("chmod 600 /root/.ssh/known_hosts")

        # Read specific node cert/key from node1
        _, node_crt, _ = node1.execute(f"cat /var/lib/hci/certs_staging/node-{node.ip}.crt")
        _, node_key, _ = node1.execute(f"cat /var/lib/hci/certs_staging/node-{node.ip}.key")

        node.write_file("/etc/hci/spark/certs/ca.crt", ca_crt)
        node.write_file("/etc/hci/spark/certs/node.crt", node_crt)
        node.write_file("/etc/hci/spark/certs/node.key", node_key)
        node.execute("chmod 600 /etc/hci/spark/certs/node.key")

        print(f"[{node.ip}] Distributing SSL certificate for Slate/Traefik...")
        node.execute("mkdir -p /etc/hci/spectrum/certs")
        node.write_file("/etc/hci/spectrum/certs/server.crt", shared_ssl_crt)
        node.write_file("/etc/hci/spectrum/certs/server.key", shared_ssl_key)
        node.execute("chmod 600 /etc/hci/spectrum/certs/server.key")

        print(f"[{node.ip}] Restarting services to pick up certificates...")
        try:
            node.execute("systemctl restart spark-daemon")
        except Exception as e:
            print(f"[{node.ip}] Warning: Failed to restart spark-daemon: {e}")

        try:
            node.execute("systemctl restart spectrum")
        except Exception as e:
            print(f"[{node.ip}] Warning: Failed to restart spectrum: {e}")

        try:
            node.execute("systemctl restart agahnim")
        except Exception as e:
            print(f"[{node.ip}] Warning: Failed to restart agahnim: {e}")

        try:
            node.execute("systemctl restart slate")
        except Exception as e:
            print(f"[{node.ip}] Warning: Failed to restart slate: {e}")

    threads = []
    for node in nodes:
        t = threading.Thread(target=distribute_certs, args=(node,))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    for node in nodes:
        node.close()

    print("\n==========================================================")
    print("      Cluster Bootstrap Completed Successfully!           ")
    print("==========================================================")
    print("Starting configs are copied. You can now SSH into Node 1")
    print("and execute the cluster command to initialize the cluster:")
    print(f"  ssh root@{HOSTS[0]}")
    hosts_list_str = ",".join(HOSTS)
    print(f"  cluster -s {hosts_list_str} --redundancy_factor=1 --vip={VIP} create")
    print("==========================================================")

if __name__ == "__main__":
    main()
